mapper.update:
update position
name = #{name}, dept_id = #{deptId}, category = #{category}, semester_id = #{semesterId}, quota = #{quota}, hourly_wage = #{hourlyWage}, work_content = #{workContent}, work_location = #{workLocation}, contact_person = #{contactPerson}, contact_phone = #{contactPhone}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select

from position p
left join dept d on p.dept_id = d.id


        and p.name like concat('%', #{name}, '%')


        and p.dept_id = #{deptId}


        and p.category = #{category}


        and p.semester_id = #{semesterId}


        and p.status = #{status}


order by p.create_time desc, p.id desc

select

from position p
left join dept d on p.dept_id = d.id
where p.status = 2

    and p.name like concat('%', #{name}, '%')


    and p.dept_id = #{deptId}


    and p.category = #{category}


    and p.semester_id = #{semesterId}

order by p.publish_time desc, p.id desc
